// Cycle detection
// ─────────────────────────────────────────────────────────────────────────────

/**
 * Memoized cycle detection over a SchedulingGraph or AnalysisGraph.
 * The cache key is the graph reference; same graph ⇒ same cycles array.
 */
export const findCycles: (graph: SchedulingGraph | AnalysisGraph) => readonly Cycle[] =
  memoize1((graph: SchedulingGraph | AnalysisGraph): readonly Cycle[] => {
    const edges = graph.edges.map(e => ({ id: e.linkId, source: e.source, target: e.target }));
    return findCycles_unmemoized(graph.nodes.keys(), edges);
  });

/**
 * Memoized connected-components over the undirected projection of a
 * scheduling or analysis graph. Drives `gantt.getConnectedGroup`.
 */
export const connectedComponents: (graph: SchedulingGraph | AnalysisGraph) => readonly ConnectedGroup[] =
  memoize1((graph: SchedulingGraph | AnalysisGraph): readonly ConnectedGroup[] => {
    const edges = graph.edges.map(e => ({ id: e.linkId, source: e.source, target: e.target }));
    return connectedComponents_unmemoized(graph.nodes.keys(), edges);
  });

/**
 * `findCycleIfAdded(snapshot, candidate)` — "would adding this link close a
 * cycle?". The single candidate-cycle entry point: it backs both
 * `gantt.isCircularLink(link)` for a link that is not in the datastore yet
 * and the `onBeforeLinkAdd` / `onBeforeLinkUpdate` guard, exactly as v1
 * answered both from one `getLoopContainingLink`.
 *
 * Both the candidate and the stored links are expanded through
 * `analysisLeafReplicas`: a link to/from a derived summary stands for one link
 * per leaf descendant (v1 `_formatLink` → `_getImplicitLinks`). Without the
 * expansion a cycle that only closes through it (`A → Project` plus
 * `leaf-of-Project → A`) can still be drawn in the UI, and `findCycles()`
 * then reports the graph as cyclic — GS-3553.
 *
 * A summary ↔ own-descendant candidate is never circular (v1 `_formatLink`
 * bails out on that pair before building any relation), and neither are the
 * `s === t` replica pairs the expansion can produce.
 *
 * The check is deliberately STRUCTURAL — every stored link participates,
 * including links touching a completed task, which the analysis graph drops
 * under `use_progress`. v1 does the same for the link-add guard (v1's
 * `_preventCircularLink` switches `use_progress` off around the call) so that
 * turning progress-aware scheduling on cannot open a door for new cycles.
 * That is also why no `AnalysisGraph` is built here: `onBeforeLinkAdd` /
 * `onBeforeLinkUpdate` are latency-sensitive, and the expansion rule alone
 * (`graph/link_expansion.ts`) is all this needs.
 *
 * A candidate whose id belongs to a stored link REPLACES it (link update),
 * so the answer is about the graph as it would be, not as it is.
 *
 * Pure: does not mutate the snapshot. Caches per `05-` §G.2 — outer WeakMap
 * keyed by snapshot; inner Map keyed by
 * `${candidate.id}|${candidate.source}|${candidate.target}|${candidate.type}`
 * so the same logical candidate hits the cache regardless of object identity.
 */
const findCycleIfAddedCache = new WeakMap<Snapshot, Map<string, Cycle | null>>();

export function findCycleIfAdded(snapshot: Snapshot, candidate: LinkSnapshot): Cycle | null {
  let inner = findCycleIfAddedCache.get(snapshot);
  if (!inner) {
    inner = new Map();
    findCycleIfAddedCache.set(snapshot, inner);
  }
  const key = `${candidate.id}|${candidate.source}|${candidate.target}|${candidate.type}`;
  if (inner.has(key)) return inner.get(key) as Cycle | null;
  const result = findCycleIfAdded_impl(snapshot, candidate);
  inner.set(key, result);
  return result;
}

function findCycleIfAdded_impl(snapshot: Snapshot, candidate: LinkSnapshot): Cycle | null {
  if (isSummaryDescendantPair(snapshot, candidate.source, candidate.target)) return null;

  const candidateEdges = expandStructuralLink(snapshot, candidate);
  if (candidateEdges.length === 0) return null;

  // On `onBeforeLinkUpdate` the candidate carries the id of a link that IS
  // stored, with new endpoints — the graph to test is the stored one WITHOUT
  // that link. Filtering by id is a no-op for a plain add.
  const base = structuralEdges(snapshot).filter(e => e.id !== candidate.id);

  return findCycleWithCandidate(base, candidate.id, candidateEdges);
}

/**
 * Every stored link, expanded through derived summaries — the edge set the
 * candidate cycle check runs against. Memoized per snapshot: a link drag asks
 * the same question for many candidates within one revision.
 */
const structuralEdgesCache = new WeakMap<Snapshot, StructuralLinkEdge[]>();

function structuralEdges(snapshot: Snapshot): StructuralLinkEdge[] {
  const hit = structuralEdgesCache.get(snapshot);
  if (hit) return hit;
  const edges: StructuralLinkEdge[] = [];
  for (const link of snapshot.links) {
    for (const e of expandStructuralLink(snapshot, link)) edges.push(e);
  }
  structuralEdgesCache.set(snapshot, edges);
  return edges;
}

